  },
  {
    id: 'py-dict-get', topic: 'python', kind: 'yesno', answer: false,
    text: 'Does `d.get("missing")` raise a KeyError?',
    explain: 'No, it returns None, or the default you pass: `d.get("k", 0)`. `d["missing"]` raises.',
  },
  {
    id: 'py-keyboard-interrupt', topic: 'python', kind: 'yesno', answer: false,
    text: 'Does `except Exception:` catch a KeyboardInterrupt?',
    explain: 'No. KeyboardInterrupt derives from BaseException, not Exception, so Ctrl+C still stops the program.',
  },
  {
    id: 'py-str-mutable', topic: 'python', kind: 'yesno', answer: false,
    text: 'Can you change one character of a string in place, like `s[0] = "x"`?',
    explain: 'No, strings are immutable. Build a new one: `"x" + s[1:]`.',
  },
  {
    id: 'py-range-end', topic: 'python', kind: 'yesno', answer: true,
    text: 'Does `range(5)` stop at 4?',
    explain: 'Yes, it gives 0 to 4. The end of a range is excluded, so `range(5)` yields five values.',
  },
  {
    id: 'py-shallow-copy', topic: 'python', kind: 'yesno', answer: false,
    text: 'Does `copy.copy(outer)` also copy the lists nested inside `outer`?',
    explain: 'No, it is shallow: the nested lists are shared. Use `copy.deepcopy`.',
  },
  {
    id: 'py-sorted-in-place', topic: 'python', kind: 'yesno', answer: true,
    text: 'Does `sorted(items)` leave `items` as it was?',
    explain: 'Yes, it returns a new list. `items.sort()` is the one that sorts in place, and it returns None.',
  },
  {
    id: 'py-empty-braces', topic: 'python', kind: 'yesno', answer: true,
    text: 'Does `{}` create an empty dict?',
    explain: 'Yes. `{}` is a dict, not a set; an empty set has to be written `set()`.',
  },
  {
    id: 'py-generator-len', topic: 'python', kind: 'yesno', answer: false,
    text: 'Can you call `len()` on a generator?',
    explain: 'No, it raises TypeError: a generator does not know its length until it is used up.',
  },
  {
    id: 'py-default-eval', topic: 'python', kind: 'yesno', answer: true,
    text: 'Are default argument values evaluated once, when the function is defined?',
    explain: 'Yes. That is why a mutable default like `[]` is shared between calls.',
  },
]

files.types/index.d.ts:
/**
 * A topic a card belongs to, as a lowercase slug such as `python`, `rust` or
 * `kubernetes`. The set is open: the session's tool calls name the topic, and
 * a generated card can carry one no pack ships.
 */
export type Topic = string

/**
 * One learning card. A `fact` is read and dismissed; a `yesno` is answered
 * with 1 (yes) or 2 (no) and then explained.
 */
export type Card = {
  id: string
  topic: Topic
  kind: 'fact' | 'yesno'
  text: string
  /** The right answer of a `yesno` card. */
  answer?: boolean
  /** One or two short sentences, shown after a `yesno` is answered. */
  explain?: string
  /** `pack` for a card this plugin ships, `ai` for one a model wrote. */
  source?: 'pack' | 'ai'
}

/** What the band shows after a `yesno` card is answered. */
export type Feedback = { isRight: boolean; text: string }

/** Cards seen and answered right during the current Claude turn. */
export type TurnTally = { seen: number; asked: number; right: number }

declare module 'claude-code' {
  interface PluginState {
    holdtime: {
      card: Card | null
      feedback: Feedback | null
      needsYou: boolean
      tally: TurnTally
    }
  }
}
